public static boolean existsUser(userId _userId, InventLocationId _inventLocationId)
{
    UserGroupList list;
    MOBInventLocationsGroupRights inventLocationRights;

    select count(RecId) from inventLocationRights;

    if (inventLocationRights.RecId == 0)
    {
        //One Click setup
        return true;
    }

    while select RecID from list
        where list.userId == _userId
    join RecID from inventLocationRights
        where inventLocationRights.InventLocationId == _inventLocationId
          && inventLocationRights.UserGroupId == list.groupId
    {
        return true;
    }

    return false;
}

public static boolean exists(SysGroup _sysGroup, InventLocationId _inventLocationId)
{
    MOBInventLocationsGroupRights inventLocationRights;
    select count(RecId) from inventLocationRights;

    if (inventLocationRights.RecId == 0)
    {
        //One Click setup
        return true;
    }
    return (select firstOnly RecID from MOBInventLocationsGroupRights
                where MOBInventLocationsGroupRights.UserGroupId      == _sysGroup
                   && MOBInventLocationsGroupRights.InventLocationId == _inventLocationId).RecID != 0;

}

public static InventLocation getDefaultWarehouse()
{
    MobInventLocationsGroupRights   inventLocationRights;
    InventLocation                  inventLocation;
    UserGroupList                   userGroupList;

    select firstonly inventLocationRights order by inventLocationRights.DefaultLocation desc, inventLocationRights.InventLocationId asc
                join GroupId from userGroupList
                    where userGrouplist.userId == curUserId()
                    && inventLocationRights.UserGroupId == userGroupList.GroupId;
    inventLocation = inventLocation::find(inventLocationRights.InventLocationId);
    return inventLocation;
}
